head.script:
/************************************************************************************
 * ID           :	ULDSTF09314
 * File         :	ULDSTF09314.xml
 * Name         :	상장원부
 * Author       :	배성우
 * Description  :	상장된 상장형수익증권 상장원부 조회
 * Create Date  :	2026-09-11
************************************************************************************/

scwin.vScrenID = "ULDSTF09314.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.TR_JOB;
scwin.vBzProcsNo;
scwin.vSecugrpID = $c.lc.getGlbValue("SECUGRP_ID_PF");
scwin.gDepCd;

scwin.onpageload = function () {
    scwin.init();
};

scwin.onpageunload = function () {
};

/* 
 * 화면 초기화
 */
scwin.init = async function () {
    txb_IDX_TOTAL_CD.hide();
    label_15.setValue("");
    sbx_secugrpId.hide();
    await scwin.fn_searchCode();
};

/* 
 * selectBox 코드 리스트 세팅
 */
scwin.fn_searchCode = async function () {

    dma_codReq.set("codeList", "TRANSSTK_AGNT_CD, TAX_TP_CD, ETF_REPLICA_METHD_TP_CD"); //코드정보 List
    const sbmOptions = {
        id: "sbm_listCodeValue",
        action: "/api/listing/common/code/list-code-value",
        method: "get",
        ref: "dma_codReq",
        target: "dlt_transstkAgntCd=body.TRANSSTK_AGNT_CD, dlt_taxTpCd=body.TAX_TP_CD, dlt_etfReplicaMethdTpCd=body.ETF_REPLICA_METHD_TP_CD",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
    }
};

/* 
 * 목록 조회, LP회원 조회
 */
scwin.fn_read_sync = async function () {

    dma_selectOne.set("isuCd", ibx_searchIsuCd.getValue());
    const sbmOptions1 = {
        id: "sbm_selectOne",
        action: "/api/listing/lstproc/pf/listed-register/select-one",
        method: "get",
        ref: "dma_selectOne",
        target: "dma_selectOne=body",
        isProcessMsg: false
    };
    const res1 = await $c.sbm.executeDynamic(sbmOptions1);
    if (res1.responseJSON.success) {
        dlt_distrBasMmdd.removeAll();
        await scwin.fn_getDistrBasMmDd();
    }

    dma_lpmbrno.set("isuCd", ibx_searchIsuCd.getValue());
    const sbmOptions2 = {
        id: "sbm_selectListLpmbrno",
        action: "/api/listing/lstproc/pf/listed-register/select-list-lpmbrno",
        method: "get",
        ref: "dma_lpmbrno",
        target: "dlt_lpmbrno=body",
        isProcessMsg: false
    };
    const res2 = await $c.sbm.executeDynamic(sbmOptions2);
    if (res2.responseJSON.success) {
    }
};

/* 
 * 분배기준일 세팅
 */
scwin.fn_getDistrBasMmDd = function () {
    for (let i = 1; i <= 12; i++) {
        if (dma_selectOne.get("earngDistrBasMmdd" + i) != "") {
            dlt_distrBasMmdd.insertRow();
            dlt_distrBasMmdd.setCellData((i-1), "earngDistrBasMmdd", dma_selectOne.get("earngDistrBasMmdd" + i));
        }
    }
};

scwin.fn_CheckForm = function () {
    return true;
};

/* 
 * 수정 유효성 체크
 */
scwin.fn_update = async function () {
    scwin.TR_JOB = 'U';
    if (await scwin.fn_CheckForm()) {
        if (!await $c.data.isModified(dma_selectOne)) {
            $c.win.alert($c.data.getMessage("com_crud_0202"));
            return;
        }
        if (!await $c.lc.isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();

        if (String(scwin.vBzProcsNo).length != 14) {
            $c.win.alert($c.data.getMessage("com_complete_0151", "업무처리번호생성"));
        } else {
            await scwin.fn_trs("2");
        }
    }
};

/* 
 * 저장/수정/삭제 기능
 */
scwin.fn_trs = async function (trsIdx) {
    dma_selectOne.set("bzProcsNo", scwin.vBzProcsNo);
    const sbmOptions = {
        id: "sbm_listCodeValue",
        action: "/api/listing/lstproc/pf/listed-register/modify",
        method: "post",
        ref: "dma_selectOne",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        $c.win.alert($c.data.getMessage("com_complete_0150", "수정"));
        await scwin.fn_read_sync();
    }
};

/* 
 * 조회 버튼
 */
scwin.btn_search_onclick = async function () {
    if ($c.stf.getObjectValue(ibx_searchIsuCd) == "") {
        await $c.win.alert($c.data.getMessage("com_req_select", "종목"));
        ibx_searchIsuCd.focus();
        return;
    }
    await scwin.fn_read_sync();
};

/* 
 * 종목코드 검색 팝업
 */
scwin.btn_searchIsu_onclick = async function () {
    // $c.stockSearch.JongmokSearch(ibx_searchIsuCd, ibx_searchIsuNm, scwin.vSecugrpID, js_market, "A");
    const res = await $c.cm.jongmokSearch(ibx_searchIsuCd, ibx_searchIsuNm, scwin.vSecugrpID, $c.session.getUserInfo("market"), "A");
    ibx_searchIsuCd.setValue(res.isuCd);
    ibx_searchIsuNm.setValue(res.isuKorNm);

    await scwin.fn_read_sync();
};

/* 
 * 수정 버튼
 */
scwin.btn_update_onclick = function () {
    scwin.fn_update();
};

scwin.dma_selectOne_OnLoadCompleted = function (rowcount) {
    dlt_distrBasMmdd.removeAll();
    scwin.fn_getDistrBasMmDd();
};
